def get_digits(n):
    """Returns a list of digits of n."""
    return [int(d) for d in str(n)]

def is_distinct_nonzero(n):
    """Checks if n consists of distinct, nonzero digits."""
    s = str(n)
    digits = set()
    for char in s:
        d = int(char)
        if d == 0:
            return False
        if d in digits:
            return False
        digits.add(d)
    return True

# Cache for storing results of is_good(m)
is_good_cache = {}

def is_good(m):
    """
    Checks if m is a 'good' number based on the definition.
    Uses memoization.
    """
    if m in is_good_cache:
        return is_good_cache[m]

    s_m = str(m)
    k = len(s_m)

    # Base case: single-digit number
    if k == 1:
        is_good_cache[m] = True
        return True

    # Recursive case: check if removing any digit results in a good divisor
    for i in range(k):
        # Form the number m_prime by removing the digit at index i
        s_m_prime = s_m[:i] + s_m[i+1:]

        # Handle the case where s_m_prime might be empty (only if k=1, but k>1 here)
        if not s_m_prime:
            continue

        m_prime = int(s_m_prime)

        # Condition 1: m_prime must be a divisor of m
        if m % m_prime == 0:
            # Condition 2: m_prime must be a good number
            if is_good(m_prime):
                is_good_cache[m] = True
                return True

    # If no such m_prime is found
    is_good_cache[m] = False
    return False

def find_all_good_numbers_up_to_1000():
    """
    Finds all good numbers m < 1000 with distinct nonzero digits.
    """
    good_numbers = []

    # Iterate through all candidates m < 1000
    for m in range(1, 1000):
        if is_distinct_nonzero(m):
            if is_good(m):
                good_numbers.append(m)

    return sorted(good_numbers)

# Run the finding process
good_numbers = find_all_good_numbers_up_to_1000()

print(f"Total good numbers found: {len(good_numbers)}")
print(f"Good numbers list: {good_numbers}")

# Optional: Print structure for easier recording
good_numbers_dict = {}
for m in good_numbers:
    good_numbers_dict[m] = {
        'digits': [int(d) for d in str(m)],
        'is_good': True
    }

# A structured output is better for the notes
