for m in good_numbers:
    s_m = str(m)
    digits = [d for d in s_m]
    print(f"M={m} (Digits: {digits})")

    # Detailed check for notes (optional, but helpful for verification)
    if len(digits) > 1:
        is_verified = False
        for i in range(len(digits)):
            s_prime = s_m[:i] + s_m[i+1:]
            m_prime = int(s_prime)

            if m % m_prime == 0:
                if is_good_cache.get(m_prime, False):
                    is_verified = True
                    break
        print(f"  -> Verified via sub-number: {is_verified}")

